rss.channel:
    Stefan VanBuren · All Content
    {{ .Permalink }}
    All content on stefan.vanburen.xyz
    Hugo -- gohugo.io
    {{.Site.LanguageCode}}
    {{ $email := .Site.Author.email }}
    {{ $name := .Site.Author.name }}
    {{$email}} ({{$name}})
    {{$email}} ({{$name}})
    {{.Site.Copyright}}
    {{ if not .Date.IsZero }}
    {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
    {{ end }}
    {{ with .OutputFormats.Get "RSS" }}
      {{ printf "" .Permalink .MediaType | safeHTML }}
    {{ end }}
    {{ range where (where .Site.RegularPages "Type" "in" site.Params.mainSections) "Draft" "!=" true }}


      {{ .Title }}
      {{ .Permalink }}
      {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
      {{$email}} ({{$name}})
      {{ .Permalink }}

        {{ .Content | html }}

	{{ with partial "rss-footer.html" . }}
	{{ . | html }}
	{{ end }}


    {{ end }}
